begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('80000000-0000-4000-8000-000000000001','notification_a@example.test'),('80000000-0000-4000-8000-000000000002','notification_b@example.test');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000001',true);
select public.complete_onboarding('notification_a','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','B1','America/Toronto');
set local role authenticated;
select is(public.get_notification_preferences()->>'daily_time','08:00:00','Daily default is 8 AM');
select is(public.get_notification_preferences()->>'streak_time','19:00:00','Streak default is 7 PM');
select is(public.get_notification_preferences()->>'timezone','America/Toronto','Preference timezone is persisted learning timezone');
select is(public.get_notification_preferences()->>'delivery_available','true','Sender capability is available under approved contract');
select is(public.save_notification_preferences(true,false,true,'09:15','20:10')->>'daily_words','false','Own daily preference can be disabled');
select throws_ok($$select public.save_notification_preferences(true,true,true,'24:00','19:00')$$,'22023','invalid_notification_preferences','Reject invalid clock boundary');
select throws_ok($$select public.save_notification_preferences(null,true,true,'08:00','19:00')$$,'22023','invalid_notification_preferences','Reject null preference');
select throws_ok($$select * from public.notification_preferences$$,'42501',null,'Raw preference cross-user read denied');
select throws_ok($$update public.notification_preferences set enabled=true$$,'42501',null,'Direct preference mutation denied');
select throws_ok($$select public.prepare_due_notifications()$$,'42501',null,'Client cannot schedule or mark notifications sent');
select throws_ok($$select * from private.notification_deliveries$$,'42501',null,'Delivery history private');
select throws_ok($$select * from private.push_installations$$,'42501',null,'Push tokens and installation secrets private');
reset role;
select throws_ok($$insert into private.notification_deliveries(user_id,kind,local_date,timezone,challenge_id,title,body,words) values('80000000-0000-4000-8000-000000000001','DAILY_WORDS',current_date,'UTC',gen_random_uuid(),'title','body',null)$$,'23514',null,'Daily preparation cannot contain a missing word snapshot');
select throws_ok($$insert into private.notification_deliveries(user_id,kind,local_date,timezone,title,body,state) values('80000000-0000-4000-8000-000000000001','STREAK_AT_RISK',current_date,'UTC','title','body','sent')$$,'23514',null,'No privileged caller can claim a successful delivery in this phase');
select is(private.next_notification_check('America/Toronto','2026-03-08 06:59Z','08:00','19:00'),'2026-03-08 12:00Z'::timestamptz,'Spring DST uses local 8 AM');
select is(private.next_notification_check('America/Toronto','2026-11-01 04:00Z','08:00','19:00'),'2026-11-01 13:00Z'::timestamptz,'Fall DST uses local 8 AM');
select is(private.next_notification_check('America/Toronto','2026-03-08 06:00Z','02:30',null),'2026-03-08 07:30Z'::timestamptz,'Missing local time moves forward through DST gap');
select is(private.next_notification_check('America/Toronto','2026-11-01 04:00Z','01:30',null),'2026-11-01 06:30Z'::timestamptz,'Ambiguous local time resolves to standard-time occurrence');
select is(private.next_notification_check('Pacific/Auckland','2026-09-15 12:01Z','08:00','19:00'),'2026-09-15 20:00Z'::timestamptz,'Local midnight rollover uses persisted zone');
select is(private.next_notification_check('UTC','2026-09-15 08:00Z','08:00','19:00'),'2026-09-15 19:00Z'::timestamptz,'After daily time next check targets evening');
select is(private.next_notification_check('UTC','2026-09-15 07:59Z','08:00',null),'2026-09-15 08:00Z'::timestamptz,'Before 8 AM remains scheduled for 8');
select is(private.next_notification_check('UTC','2026-09-15 09:00Z','10:15',null),'2026-09-15 10:15Z'::timestamptz,'Custom time schedules correctly');
select throws_ok($$select public.prepare_due_notifications(101)$$,'22023','invalid_notification_batch','Scheduler bounded to 100 users');
set local role anon;
select throws_ok($$select public.get_notification_preferences()$$,'42501',null,'Anonymous preferences denied');
select throws_ok($$select public.sync_push_installation(gen_random_uuid(),'short',1)$$,'22023','invalid_push_installation','Invalid capability rejected');
reset role;
select * from finish();
rollback;
